{
  "summary": "Construct and run a table-based optimization tool to solve the inventory selection problem with constraints",
  "actions": [
    {
      "tool": "construct_table",
      "name": "inventory_optimization.json",
      "schema": {
        "events": {
          "item": "TEXT",
          "weight": "INTEGER",
          "points": "INTEGER",
          "compatibility": "TEXT"
        }
      },
      "sql": "SELECT item, weight, points, compatibility FROM events"
    },
    {
      "tool": "run_table",
      "name": "inventory_optimization.json",
      "input": {
        "dataset": "inventory_optimization",
