          "events": [
            {"item": "optic", "weight": 5, "points": 11, "compatibility": "mount"},
            {"item": "mount", "weight": 2, "points": 2, "compatibility": "optic"},
            {"item": "torch", "weight": 3, "points": 8, "compatibility": "gauge"},
            {"item": "gauge", "weight": 4, "points": 9, "compatibility": "torch"},
